-- Script 200 · Organización 2 (Hospital Miraflores): 87417 líneas del detalle contable de las compras del sistema anterior
--   (ACT_DETCON_COMPRAS.xls y ACT_DETCON_COMPRAS_PARTE_2.xls). Se ejecuta después del script 198 (compras).
--   Cada línea se liga a su compra por el número del sistema anterior; LINEA = línea; la cuenta se busca por su código en la versión
--   VERSION del catálogo de la localidad (todas existen en el catálogo del script 177). CENTRO = centro de costo (0 = sin centro);
--   los centros que no existen se crean. DEBITO = debe, CREDITO = haber.
--   Líneas con débito y crédito a la vez (queda la diferencia; los del archivo en debe_anterior y haber_anterior): 2-01 compra 9648 línea 3, 2-01 compra 9649 línea 3, 2-01 compra 9662 línea 3.
--   No se migran 30 líneas de las compras sin valor total que el script 198 no migra.
--   Columnas nuevas: centro_costo_anterior, debe_anterior y haber_anterior (cuenta_codigo_anterior y version_cuenta_anterior son del script 106).
--   Para el SQL Editor de Supabase están también por separado en supabase/pendientes/200_compras_contable_parte_N_de_16.sql.

-- Script 200 · parte 1 de 16 · Organización 2: detalle contable de las compras (ACT_DETCON_COMPRAS y _PARTE_2), 5576 líneas.
-- Se ejecuta después del script 198 (compras). Se puede ejecutar de nuevo: la segunda vez solo actualiza.
alter table public.compra_lineas add column if not exists cuenta_codigo_anterior text;
alter table public.compra_lineas add column if not exists version_cuenta_anterior integer;
alter table public.compra_lineas add column if not exists centro_costo_anterior text;
alter table public.compra_lineas add column if not exists debe_anterior numeric(18, 2);
alter table public.compra_lineas add column if not exists haber_anterior numeric(18, 2);
alter table public.compra_lineas add column if not exists reconstruida boolean not null default false;

do $detcon$
declare
  v_org bigint; v_loc bigint; v_kc bigint; v_may bigint; r record; v_n int := 0; v_a int := 0; v_cen int := 0; v_sin_compra int; v_sin_cuenta text; v_rec int;
begin
  select id into v_org from public.organizaciones where codigo = '2';
  if v_org is null then raise notice 'No existe la organización 2.'; return; end if;

  -- a) Centros de costo de las líneas que no existen en el catálogo de centros de la localidad: se crean (el 0 es «sin centro»).
  for r in select * from (values (1, '308'), (1, '303'), (1, '307'), (1, '10601'), (1, '2010101'), (1, '30104'), (1, '30402'), (1, '2010201'), (1, '306'), (1, '10602'), (1, '30401'), (1, '102'), (1, '2010206'), (1, '101'), (1, '2020501'), (1, '2020308'), (1, '2010203'), (2, '309')) as x(loc, codigo) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    if v_loc is null then continue; end if;
    v_kc := null;
    select id into v_kc from public.catalogos_centros where localidad_id = v_loc order by (version = 1) desc, activo desc, version limit 1;
    if v_kc is null then
    end if;
    if exists (select 1 from public.centros_costo where catalogo_id = v_kc and codigo = r.codigo) then continue; end if;
    v_may := null;
    select id into v_may from public.centros_costo where catalogo_id = v_kc and length(codigo) < length(r.codigo) and left(r.codigo, length(codigo)) = codigo order by length(codigo) desc limit 1;
    values (v_org, v_kc, r.codigo, 'CENTRO DE COSTO ' || r.codigo || ' (CREADO AL MIGRAR COMPRAS)', v_may, true, r.codigo);
    v_cen := v_cen + 1;
  end loop;

  drop table if exists m_l;
  create temp table m_l (loc integer, compra integer, linea integer, cuenta text, version integer, centro text, debe numeric, haber numeric, debe_ant numeric, haber_ant numeric);

  select count(*) into v_sin_compra from m_l m where not exists (
    select 1 from public.localidades l join public.compras c on c.localidad_id = l.id and c.origen_anterior = 'VARIAS' and c.compra_anterior = m.compra
    where l.organizacion_id = v_org and l.correlativo = m.loc);
  select string_agg(distinct format('2-0%s %s', m.loc, m.cuenta), ', ') into v_sin_cuenta from m_l m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  where not exists (select 1 from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
                    where g.localidad_id = l.id and k.codigo = m.cuenta and (g.version = m.version or m.version is null));

  -- Las validaciones de la pantalla (compra anulada o con partida) se suspenden durante la carga.
  alter table public.compra_lineas disable trigger compra_lineas_validar;
  -- Las líneas que el script 168 reconstruyó en estas compras se reemplazan por las del sistema anterior.
  delete from public.compra_lineas cl using m_l m, public.localidades l, public.compras c
  where l.organizacion_id = v_org and l.correlativo = m.loc and c.localidad_id = l.id and c.origen_anterior = 'VARIAS' and c.compra_anterior = m.compra
    and cl.compra_id = c.id and cl.reconstruida;
  get diagnostics v_rec = row_count;
  with x as (
    select c.id, m.linea, k.id, m.debe, m.haber,
           (select z.id from public.centros_costo z join public.catalogos_centros kc on kc.id = z.catalogo_id
            where kc.localidad_id = l.id and z.codigo = m.centro order by (kc.version = 1) desc, kc.activo desc limit 1),
           m.cuenta, m.version, m.centro, m.debe_ant, m.haber_ant
    from m_l m
    join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
    join public.compras c on c.localidad_id = l.id and c.origen_anterior = 'VARIAS' and c.compra_anterior = m.compra
    join lateral (select k.id from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
                  where g.localidad_id = l.id and k.codigo = m.cuenta and (g.version = m.version or m.version is null)
                  order by g.version desc limit 1) k on true
    on conflict (compra_id, linea) do update set cuenta_id = excluded.cuenta_id, debe = excluded.debe, haber = excluded.haber, centro_id = excluded.centro_id,
      cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      centro_costo_anterior = excluded.centro_costo_anterior, debe_anterior = excluded.debe_anterior, haber_anterior = excluded.haber_anterior, reconstruida = false
    returning (xmax = 0) as nueva)
  select count(*) filter (where nueva), count(*) filter (where not nueva) into v_n, v_a from x;
  alter table public.compra_lineas enable trigger compra_lineas_validar;

  raise notice '%', format('Detalle contable de compras de la organización 2 (parte 1 de 16): %s líneas nuevas, %s actualizadas.%s%s%s%s',
    v_n, v_a,
    case when v_cen > 0 then format(' %s centros de costo creados.', v_cen) else '' end,
    case when v_rec > 0 then format(' %s líneas reconstruidas reemplazadas.', v_rec) else '' end,
    case when v_sin_compra > 0 then format(' %s líneas de compras que no existen (omitidas: ejecuta antes el script 198).', v_sin_compra) else '' end,
    case when v_sin_cuenta is not null then ' Cuentas que no existen en el catálogo (líneas omitidas): ' || v_sin_cuenta || '.' else '' end);
  drop table m_l;
end;
$detcon$;

